import{z as d,x as l,o as r,c,q as i,j as A,D as e,d as s,s as E,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"扩展属性与 ACL","description":"","frontmatter":{"title":"扩展属性与 ACL","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/xattr-acl.md","filePath":"cs/xattr-acl.md","lastUpdated":1791413859000}'),p={name:"cs/xattr-acl.md"};function C(u,a,B,m,x,S){const o=l("Mermaid");return r(),c("div",null,[a[2]||(a[2]=i('<h1 id="扩展属性与-acl" tabindex="-1">扩展属性与 ACL <a class="header-anchor" href="#扩展属性与-acl" aria-label="Permalink to &quot;扩展属性与 ACL&quot;">​</a></h1><div class="epigraph"><p>inode 上除了模式位，还可以挂键值对；ACL 把「谁能对这个对象做什么」写成可列举的条目，而不只是 ugo 三位。</p><footer>—— 据 POSIX ACL 草案与 NFSv4 ACL 实践；Linux xattr 文档；McKusick 对扩展属性存放的讨论</footer></div><p><a href="/cs/sparse-files">上一课</a>把数据洞说清。元数据仍停在 <a href="/cs/inode-dir">inode</a> 的模式、uid、gid。缺口是 <strong>xattr</strong>：任意名空间里的键值；以及用它（或并行结构）实现的 ACL。本课不把 SELinux 标签的策略写成安全课全文——那是 LSM 后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>备份系统、SELinux、capabilities 落地、用户注释都需要「不进文件字节」的旁路数据。若全塞进目录项，FAT 那样的定长槽放不下。Unix 把扩展属性挂到 inode：<code>user.*</code> 可用户写，<code>security.*</code>、<code>system.*</code> 受特权约束。POSIX ACL 常存在 <code>system.posix_acl_access</code> 等键里。缺口：查找路径上要不要继承默认 ACL；权限检查在 VFS 还是 FS；与 <a href="/cs/vfs">VFS</a> 操作表如何接头。</p><p><span class="marginnote">术语翻译：xattr 就是挂在 inode 旁边的「键值便签」——键如 user.comment，值是任意字节，不占文件内容本身。user.* 前缀普通用户可写；security.<em>、system.</em> 只有特权进程碰。前缀本身就是权限边界。</span></p><p><span class="marginnote">属性值可放 inode 内联或外置块。列表过大则 <code>listxattr</code> 昂贵。ACL_MASK 与 named user 的计算顺序是规范细节，课序只要求「模式位不是唯一裁决」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>setxattr</code>：VFS 检查名空间权限，调 FS 把键值写入 inode 旁路块或内联区，可能进 <a href="/cs/ext4-journal">日志</a> 事务。<code>getxattr</code> 读回。打开文件时，若启用 ACL，VFS 用 ACL 条目代替简单 <code>mode &amp; umask</code> 裁决。拷贝文件若不用 <code>cp --preserve=xattr</code>，属性会丢——这是用户工具问题，对象仍在 inode 上。</p><p><span class="marginnote">常见误区：以为 cp 复制文件连注释一起带走。默认 cp 只拷数据与基本模式位，xattr 要加 --preserve=xattr 才跟上。备份脚本忘写这一项，SELinux 标签、能力集会静默丢失，事后才发现权限对不上。</span></p>',10)),(r(),A(n,null,{default:e(()=>[E(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20NAME%5B%22%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20INO%5B%22inode%22%5D%0A%20%20INO%20--%3E%20MODE%5B%22%E4%BC%A0%E7%BB%9F%E6%A8%A1%E5%BC%8F%E4%BD%8D%22%5D%0A%20%20INO%20--%3E%20XA%5B%22xattr%20%E9%94%AE%E5%80%BC%22%5D%0A%20%20XA%20--%3E%20ACL%5B%22ACL%20%E6%9D%A1%E7%9B%AE%22%5D%0A%20%20ACL%20--%3E%20DEC%5B%22VFS%20%E6%9D%83%E9%99%90%E8%A3%81%E5%86%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[s("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"xattr 让文件系统成为可扩展的对象存储：安全模块、overlay 白名单、能力集都可以不改盘格式主结构。ACL 把「组不够用」从二次开发里收回内核。不要把 ACL 写成数据库行级安全：没有 SQL，只有对 inode 的访问谓词。",-1)),a[5]||(a[5]=t("p",null,"ACL 条目按什么顺序裁决一次打开：",-1)),(r(),A(n,null,{default:e(()=>[E(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHK%5B%22%E6%89%93%E5%BC%80%E6%96%87%E4%BB%B6%E7%9A%84%E6%9D%83%E9%99%90%E6%A3%80%E6%9F%A5%22%5D%20--%3E%20O%7B%22uid%20%E6%98%AF%E5%B1%9E%E4%B8%BB%E5%90%97%22%7D%0A%20%20O%20--%3E%7C%22%E6%98%AF%22%7C%20R1%5B%22%E6%8C%89%20owner%20%E6%9D%A1%E7%9B%AE%E5%AE%9A%E5%A4%BA%22%5D%0A%20%20O%20--%3E%7C%22%E5%90%A6%22%7C%20N%7B%22%E5%91%BD%E4%B8%AD%20named%20user%20%E6%9D%A1%E7%9B%AE%E5%90%97%22%7D%0A%20%20N%20--%3E%7C%22%E6%98%AF%22%7C%20M1%5B%22%E5%85%88%E4%B8%8E%20ACL_MASK%20%E6%B1%82%E4%BA%A4%E5%86%8D%E5%AE%9A%E5%A4%BA%22%5D%0A%20%20N%20--%3E%7C%22%E5%90%A6%22%7C%20G%7B%22%E5%B1%9E%E7%BB%84%E6%88%96%20named%20group%22%7D%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20M2%5B%22%E5%90%8C%E6%A0%B7%E5%8F%97%20MASK%20%E6%88%AA%E6%96%AD%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20R2%5B%22%E6%8C%89%20other%20%E6%9D%A1%E7%9B%AE%E5%AE%9A%E5%A4%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>与 FAT：若干实现把 ACL 塞进 EA 流，仍是目录项旁路，不是 Unix inode 号。NFS 是否传送 ACL 是 <a href="/cs/nfs-semantics">NFS 语义</a> 的缺口，本课只钉本地 VFS。</p><p><span class="marginnote">为什么重要：MASK 是给 named user/group 的「总闸」——条目写明 rwx，被 MASK 截到 r-- 就只剩读。只看 mode 的 group 位判权限会误判；规范要求先过 MASK 再合并，这就是那句「计算顺序」细节的实指。</span></p><p>实现上：POSIX ACL 的 mask 项会截断 named user/group 的有效权限，只看 mode 的 group 位会误判。security xattr 给 LSM 用，user xattr 可被配额计入数据块。 读法上只引用<a href="/cs/sparse-files">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 布局与日志」课序里，对象是 <strong>扩展属性与 ACL</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 RichACL 的全部 NFSv4 权限位。不保证每个导出的 FUSE 都实现 xattr。下一课用同一套 inode 记账：配额何时在分配路径上扣减。</p><p>版本字段会变，课序钉的是机制对象「扩展属性与 ACL」，不是某一主线内核的结构体名。 后课默认：inode 可挂键值与 ACL。用户与项目的空间/inode 上限，下一课配额。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>xattr 是 inode 旁路键值；ACL 常存在其中。</li><li>VFS 在打开与创建路径上用 ACL 裁决。</li><li>配额是下一课。</li><li>出处：POSIX ACL；Linux <code>xattr(7)</code>；McKusick；NFSv4 ACL 概述。</li></ul>',10))])}const h=d(p,[["render",C]]);export{D as __pageData,h as default};
